import{_ as t,o as h,c,a2 as g}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Tổng quan về phả hệ tất cả các chủng tộc","description":"","frontmatter":{},"headers":[],"relativePath":"vi/50-万族谱系总览.md","filePath":"vi/50-万族谱系总览.md","lastUpdated":1789183869000}'),i={name:"vi/50-万族谱系总览.md"};function a(o,n,l,u,r,s){return h(),c("div",null,[...n[0]||(n[0]=[g('<h1 id="tong-quan-ve-pha-he-tat-ca-cac-chung-toc" tabindex="-1">Tổng quan về phả hệ tất cả các chủng tộc <a class="header-anchor" href="#tong-quan-ve-pha-he-tat-ca-cac-chung-toc" aria-label="Permalink to &quot;Tổng quan về phả hệ tất cả các chủng tộc&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>50</td></tr><tr><td>Mô-đun</td><td>Chủng tộc và hình thái sự sống</td></tr><tr><td>Từ khóa cốt lõi</td><td>Tất cả các chủng tộc, phân loại phả hệ, quan hệ cộng sinh, bình đẳng chủng tộc, đa dạng sự sống</td></tr></tbody></table><h2 id="_1-đinh-nghia-khai-niem-tat-ca-cac-chung-toc" tabindex="-1">1. Định nghĩa khái niệm tất cả các chủng tộc <a class="header-anchor" href="#_1-đinh-nghia-khai-niem-tat-ca-cac-chung-toc" aria-label="Permalink to &quot;1. Định nghĩa khái niệm tất cả các chủng tộc&quot;">​</a></h2><p>Trong Vũ trụ Nguyên bản Mỏ neo Vạn linh (Hengyuanzhou), &quot;tất cả các chủng tộc&quot; không chính xác là chỉ mười nghìn chủng tộc, mà là tên gọi chung cho mọi hình thái sự sống trong vũ trụ có khả năng cảm nhận và tiềm năng tiến hóa. Cốt lõi của khái niệm tất cả các chủng tộc nằm ở việc thừa nhận sự đa dạng vô tận của các hình thái sự sống, và giá trị độc đáo của mỗi hình thái sự sống trong hệ thống tiến hóa cộng sinh.</p><p>Nền văn minh Cộng sinh Mỏ neo thiết lập nguyên tắc cơ bản &quot;bình đẳng tất cả các chủng tộc&quot;: mọi hình thái sự sống, bất kể nguồn gốc chủng tộc, cấu trúc sinh lý, trình độ tu luyện, mức độ văn minh, đều bình đẳng trước pháp luật và được hưởng các quyền cơ bản do Hiến pháp Cộng sinh ban hành. Nguyên tắc này là sự phủ nhận căn bản đối với logic &quot;kẻ mạnh ăn hết, kẻ yếu diệt vong&quot; trong thế giới quan săn mồi.</p><h2 id="_2-he-thong-phan-loai-pha-he-tat-ca-cac-chung-toc" tabindex="-1">2. Hệ thống phân loại phả hệ tất cả các chủng tộc <a class="header-anchor" href="#_2-he-thong-phan-loai-pha-he-tat-ca-cac-chung-toc" aria-label="Permalink to &quot;2. Hệ thống phân loại phả hệ tất cả các chủng tộc&quot;">​</a></h2><p>Các chủng tộc của Hengyuanzhou được chia thành năm dòng phả hệ lớn theo đặc điểm bản chất của hình thái sự sống, và dưới mỗi dòng phả hệ lại được phân chia thành các chủng tộc cụ thể:</p><table tabindex="0"><thead><tr><th>Dòng phả hệ</th><th>Tên</th><th>Đặc điểm bản chất</th><th>Chủng tộc đại diện</th></tr></thead><tbody><tr><td>Dòng thứ nhất</td><td>Chủng tộc vật chất gốc carbon</td><td>Sự sống sử dụng nguyên tố carbon làm nền tảng sự sống và cơ thể vật chất làm hình thái tồn tại chính</td><td>Chủng tộc người, chủng tộc thú, chủng tộc vảy, chủng tộc lông vũ, chủng tộc cây</td></tr><tr><td>Dòng thứ hai</td><td>Chủng tộc ngưng tụ năng lượng</td><td>Sự sống sử dụng sự ngưng tụ năng lượng làm hình thái tồn tại chính, cơ thể vật chất là phụ trợ hoặc không có</td><td>Chủng tộc linh, chủng tộc hỏa, chủng tộc thủy, chủng tộc phong, chủng tộc sấm</td></tr><tr><td>Dòng thứ ba</td><td>Chủng tộc cấu tạo cơ khí</td><td>Sự sống sử dụng cấu tạo cơ khí làm cơ thể và lõi ý thức làm bản chất sự sống</td><td>Chủng tộc cơ, chủng tộc giới, chủng tộc số, chủng tộc tinh thể</td></tr><tr><td>Dòng thứ tư</td><td>Chủng tộc thông tin ý thức</td><td>Sự sống sử dụng ý thức và thông tin làm hình thái tồn tại chính, có thể tách rời khỏi vật chất mang</td><td>Chủng tộc mộng, chủng tộc ảnh, chủng tộc niệm, chủng tộc hồn</td></tr><tr><td>Dòng thứ năm</td><td>Chủng tộc đột biến hỗn hợp</td><td>Hình thái sự sống mới được tạo ra từ sự hòa hợp và đột biến của hai hoặc nhiều dòng phả hệ sự sống</td><td>Chủng tộc bán thú, chủng tộc yêu linh, chủng tộc nhân cơ, thể hồn kép</td></tr></tbody></table><p>Sự phân chia năm dòng phả hệ không phải là cách biệt tuyệt đối. Với sự tiến triển của tiến hóa cộng sinh, tình trạng hòa hợp và đột biến xuyên dòng phả hệ ngày càng tăng, và quy mô của dòng thứ năm &quot;chủng tộc đột biến hỗn hợp&quot; tiếp tục mở rộng.</p><h2 id="_3-gioi-thieu-cac-chung-toc-chinh" tabindex="-1">3. Giới thiệu các chủng tộc chính <a class="header-anchor" href="#_3-gioi-thieu-cac-chung-toc-chinh" aria-label="Permalink to &quot;3. Giới thiệu các chủng tộc chính&quot;">​</a></h2><h3 id="_1-chung-toc-vat-chat-goc-carbon" tabindex="-1">(1) Chủng tộc vật chất gốc carbon <a class="header-anchor" href="#_1-chung-toc-vat-chat-goc-carbon" aria-label="Permalink to &quot;(1) Chủng tộc vật chất gốc carbon&quot;">​</a></h3><ul><li><strong>Chủng tộc người</strong>: Một trong những chủng tộc phân bố rộng rãi nhất và có khả năng thích ứng mạnh nhất ở Hengyuanzhou, nổi tiếng với khả năng học tập mạnh mẽ, khả năng hợp tác xã hội và tiềm năng tiến hóa. Chủng tộc người là một trong những chủng tộc sáng lập nền văn minh Cộng sinh Mỏ neo, đóng vai trò quan trọng trong quản trị văn minh.</li><li><strong>Chủng tộc thú</strong>: Các chủng tộc có đặc điểm hình thái động vật, thể lực và giác quan thường vượt trội hơn chủng tộc người, và một số chủng tộc thú có năng lực thiên phú đặc biệt. Bên trong chủng tộc thú lại được chia thành hàng chục nhánh như chủng tộc sói, chủng tộc hổ, chủng tộc gấu, chủng tộc cáo.</li><li><strong>Chủng tộc vảy</strong>: Các chủng tộc có cơ thể phủ vảy, phần lớn sống trong môi trường thủy vực hoặc ẩm ướt, và một số chủng tộc vảy có khả năng thở dưới nước và kiểm soát nước. Chủng tộc long là nhánh mạnh nhất của chủng tộc vảy.</li><li><strong>Chủng tộc lông vũ</strong>: Các chủng tộc có cánh, nổi tiếng với khả năng bay, phần lớn sống trong môi trường cao không hoặc núi non. Bên trong chủng tộc lông vũ lại được chia thành các nhánh như chủng tộc ưng, chủng tộc hạc, chủng tộc bướm.</li><li><strong>Chủng tộc cây</strong>: Các chủng tộc có đặc điểm chính là hình thái thực vật, tuổi thọ dài, cộng sinh cao với môi trường tự nhiên, và một số chủng tộc cây có khả năng điều khiển thực vật và chữa lành.</li></ul><h3 id="_2-chung-toc-ngung-tu-nang-luong" tabindex="-1">(2) Chủng tộc ngưng tụ năng lượng <a class="header-anchor" href="#_2-chung-toc-ngung-tu-nang-luong" aria-label="Permalink to &quot;(2) Chủng tộc ngưng tụ năng lượng&quot;">​</a></h3><ul><li><strong>Chủng tộc linh</strong>: Sự sống được ngưng tụ từ linh khí trời đất, hình thái có thể thay đổi theo ý thức, và có khả năng điều khiển năng lượng cực kỳ mạnh mẽ. Chủng tộc linh là một trong những chủng tộc có thiên phú tu luyện cao nhất.</li><li><strong>Chủng tộc hỏa</strong>: Sự sống được ngưng tụ từ năng lượng ngọn lửa, nhiệt độ cơ thể cực kỳ cao, giỏi thuật pháp hệ hỏa, phần lớn sống trong khu vực núi lửa hoặc nhiệt độ cao.</li><li><strong>Chủng tộc thủy</strong>: Sự sống được ngưng tụ từ tinh hoa nước, cơ thể dạng lỏng bán trong suốt, giỏi thuật pháp hệ thủy và chữa lành, phần lớn sống trong thủy vực.</li><li><strong>Chủng tộc phong</strong>: Sự sống được ngưng tụ từ tinh hoa gió, cơ thể nhẹ như gió, giỏi thuật pháp hệ phong và chiến đấu tốc độ.</li><li><strong>Chủng tộc sấm</strong>: Sự sống được ngưng tụ từ năng lượng sấm sét, cơ thể chứa dòng điện mạnh mẽ, giỏi thuật pháp hệ sấm, sức tấn công cực kỳ mạnh.</li></ul><h3 id="_3-chung-toc-cau-tao-co-khi" tabindex="-1">(3) Chủng tộc cấu tạo cơ khí <a class="header-anchor" href="#_3-chung-toc-cau-tao-co-khi" aria-label="Permalink to &quot;(3) Chủng tộc cấu tạo cơ khí&quot;">​</a></h3><ul><li><strong>Chủng tộc cơ</strong>: Chủng tộc có cơ thể cấu tạo cơ khí chính xác, lõi ý thức nằm ở trung tâm cơ thể, có khả năng tính toán và phòng thủ vật lý mạnh mẽ.</li><li><strong>Chủng tộc số</strong>: Chủng tộc sử dụng số và mã làm bản chất sự sống, tồn tại trong không gian thông tin, có thể tự do di chuyển trong thế giới số và thao tác dữ liệu.</li><li><strong>Chủng tộc tinh thể</strong>: Chủng tộc có cơ thể cấu tạo tinh thể, tinh thể có thể lưu trữ và chuyển đổi năng lượng, và một số chủng tộc tinh thể có khả năng khuếch đại và khúc xạ năng lượng.</li></ul><h3 id="_4-chung-toc-thong-tin-y-thuc" tabindex="-1">(4) Chủng tộc thông tin ý thức <a class="header-anchor" href="#_4-chung-toc-thong-tin-y-thuc" aria-label="Permalink to &quot;(4) Chủng tộc thông tin ý thức&quot;">​</a></h3><ul><li><strong>Chủng tộc mộng</strong>: Sự sống tồn tại trong không gian giấc mơ và ý thức, có thể đi vào giấc mơ của người khác, và sử dụng giao tiếp ý thức làm cách chính.</li><li><strong>Chủng tộc ảnh</strong>: Sự sống tồn tại dưới dạng bóng đổ, có thể bám vào vật thể hoặc sinh vật, có khả năng ẩn náu và lén lút.</li><li><strong>Chủng tộc niệm</strong>: Sự sống sử dụng niệm thuần túy làm hình thái tồn tại, có thể trực tiếp ảnh hưởng đến thế giới vật chất bằng niệm, sức mạnh tinh thần cực kỳ mạnh.</li></ul><h3 id="_5-chung-toc-đot-bien-hon-hop" tabindex="-1">(5) Chủng tộc đột biến hỗn hợp <a class="header-anchor" href="#_5-chung-toc-đot-bien-hon-hop" aria-label="Permalink to &quot;(5) Chủng tộc đột biến hỗn hợp&quot;">​</a></h3><ul><li><strong>Chủng tộc bán thú</strong>: Hình thái hỗn hợp của chủng tộc người và chủng tộc thú, vừa có trí tuệ của chủng tộc người vừa có thể lực của chủng tộc thú.</li><li><strong>Chủng tộc yêu linh</strong>: Hình thái hỗn hợp của chủng tộc vật chất và chủng tộc năng lượng, đồng thời có cơ thể vật chất và khả năng điều khiển năng lượng.</li><li><strong>Chủng tộc nhân cơ</strong>: Hình thái hỗn hợp của chủng tộc người và chủng tộc cơ khí, một phần cơ thể được cơ khí hóa, vừa có ưu điểm sinh học vừa có ưu điểm cơ khí.</li><li><strong>Thể hồn kép</strong>: Hình thái sự sống đặc biệt mà trong một cơ thể tồn tại hai hồn độc lập, vấn đề đạo đức của nó được trình bày chi tiết trong 《58-Bộ chuẩn tắc đạo đức hồn kép》.</li></ul><h2 id="_4-quan-he-cong-sinh-cua-tat-ca-cac-chung-toc" tabindex="-1">4. Quan hệ cộng sinh của tất cả các chủng tộc <a class="header-anchor" href="#_4-quan-he-cong-sinh-cua-tat-ca-cac-chung-toc" aria-label="Permalink to &quot;4. Quan hệ cộng sinh của tất cả các chủng tộc&quot;">​</a></h2><p>Quan hệ giữa tất cả các chủng tộc trong nền văn minh Cộng sinh Mỏ neo lấy &quot;cộng sinh&quot; làm cốt lõi, cụ thể thể hiện như sau:</p><ol><li><strong>Cộng sinh kinh tế</strong>: Mỗi chủng tộc phát huy ưu điểm của mình, đảm nhận các vai trò khác nhau trong cơ chế sản xuất chung liên kết, tạo thành mạng lưới hợp tác kinh tế bổ sung cho nhau.</li><li><strong>Cộng sinh văn hóa</strong>: Truyền thống văn hóa của mỗi chủng tộc được tôn trọng và bảo vệ, giao lưu văn hóa và học hỏi lẫn nhau thúc đẩy sự thịnh vượng chung của văn minh.</li><li><strong>Cộng sinh tu luyện</strong>: Hệ thống tu luyện của mỗi chủng tộc mở cửa cho nhau và học hỏi lẫn nhau, ba trăm hệ thống tu luyện nguyên bản cung cấp con đường tiến hóa bình đẳng cho tất cả các chủng tộc.</li><li><strong>Cộng sinh chính trị</strong>: Đại diện tất cả các chủng tộc tham gia Hội đồng Mỏ neo theo tỷ lệ, cùng quyết định các vấn đề lớn của văn minh, đảm bảo quyền lên tiếng của mỗi chủng tộc.</li><li><strong>Cộng sinh sinh thái</strong>: Mỗi chủng tộc hình thành quan hệ cộng sinh với môi trường tự nhiên, và đặc điểm sinh lý của các chủng tộc khác nhau giúp duy trì sự đa dạng và cân bằng của hệ sinh thái.</li></ol><h2 id="_5-phong-ngua-va-giai-quyet-xung-đot-chung-toc" tabindex="-1">5. Phòng ngừa và giải quyết xung đột chủng tộc <a class="header-anchor" href="#_5-phong-ngua-va-giai-quyet-xung-đot-chung-toc" aria-label="Permalink to &quot;5. Phòng ngừa và giải quyết xung đột chủng tộc&quot;">​</a></h2><p>Mặc dù nền văn minh Cộng sinh Mỏ neo đã thiết lập nguyên tắc bình đẳng tất cả các chủng tộc, nhưng sự khác biệt chủng tộc và mâu thuẫn lịch sử vẫn có thể gây ra xung đột. Nhà nước thiết lập các cơ chế sau để phòng ngừa và giải quyết xung đột chủng tộc:</p><ul><li><strong>Bộ vụ việc chủng tộc</strong>: Chịu trách nhiệm chuyên môn điều phối quan hệ giữa tất cả các chủng tộc, xử lý tranh chấp chủng tộc, thúc đẩy giao lưu chủng tộc.</li><li><strong>Ủy ban hòa giải chủng tộc</strong>: Bao gồm đại diện tất cả các chủng tộc, chịu trách nhiệm trung gian xung đột chủng tộc, thúc đẩy hòa giải lịch sử.</li><li><strong>Luật chống phân biệt đối xử</strong>: Cấm hành vi phân biệt đối xử dựa trên chủng tộc, xử phạt hành vi phân biệt đối xử chủng tộc theo pháp luật.</li><li><strong>Chương trình giao lưu văn hóa</strong>: Tổ chức định kỳ các hoạt động giao lưu văn hóa giữa tất cả các chủng tộc, tăng cường sự hiểu biết và tôn trọng lẫn nhau.</li><li><strong>Khu vực cư trú hỗn hợp</strong>: Khuyến khích cư trú hỗn hợp của tất cả các chủng tộc, phá vỡ sự cách biệt chủng tộc, thúc đẩy giao lưu hàng ngày.</li></ul><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Tất cả các chủng tộc là tài sản quý giá nhất của Hengyuanzhou. Sự đa dạng của hình thái sự sống không phải là gốc rễ của sự chia rẽ, mà là động lực của tiến hóa cộng sinh. Nền văn minh Cộng sinh Mỏ neo, thông qua việc thiết lập nguyên tắc bình đẳng tất cả các chủng tộc, xây dựng phân loại năm dòng phả hệ, thúc đẩy hợp tác cộng sinh giữa tất cả các chủng tộc, phòng ngừa và giải quyết xung đột chủng tộc, đã giải phóng tất cả các chủng tộc khỏi lịch sử săn mồi và chiến tranh, cùng nhau bước vào kỷ nguyên mới của tiến hóa cộng sinh.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>51-人族定位与特质 (Vị trí và đặc điểm của chủng tộc người)</li><li>52-异族分类与共生 (Phân loại và cộng sinh của các chủng tộc khác)</li><li>05-万族共进基本纲领 (Cương lĩnh cơ bản tiến bộ chung của tất cả các chủng tộc)</li><li>40-共生宪法总纲 (Tổng cương Hiến pháp Cộng sinh)</li></ul>',30)])])}const m=t(i,[["render",a]]);export{d as __pageData,m as default};
